// Datos del AI
const cedula = query.cedula;
const monto = String(query.monto).split('.')[0];
const concepto = query.concepto;

// Datos deterministicos del flujo
const chat_id = $('Entrada').first().json.chat_id;
const canal = $('Entrada').first().json.canal;
const callback_url = 'https://sruedagoat.app.n8n.cloud/webhook/aura-web';

// Referencia unica generada aqui
const hoy = new Date();
const fecha = hoy.getFullYear() + String(hoy.getMonth() + 1).padStart(2, '0') + String(hoy.getDate()).padStart(2, '0');
const random = Math.floor(1000 + Math.random() * 9000);
const referencia = 'PAY-' + fecha + '-' + random;

// Construir URL
const url = 'https://sruedadev.com/pago/?' +
  'chat_id=' + encodeURIComponent(chat_id) +
  '&cedula=' + encodeURIComponent(cedula) +
  '&monto=' + encodeURIComponent(monto) +
  '&concepto=' + encodeURIComponent(concepto) +
  '&referencia=' + encodeURIComponent(referencia) +
  '&canal=' + encodeURIComponent(canal) +
  '&callback_url=' + encodeURIComponent(callback_url);

// El tool DEBE devolver un string
return 'Enlace de pago generado exitosamente. URL: ' + url + ' | Referencia: ' + referencia + ' | Monto: ' + monto;

const j = $input.first().json;
const msg = j.message || null;
return [{ json: {
  chat_id: String(j.chat_id ?? (msg && msg.chat && msg.chat.id)),
  mensaje: j.mensaje ?? (msg && msg.text) ?? '',
  canal:   j.canal ?? 'telegram',
  message: msg
}}];
